def test_package_import_exposes_jointmodel():
    jmcm = importlib.import_module("jmcm")
    assert hasattr(jmcm, "JointModel")

def test_jmcm_package_name_attribute_is_set():
    jmcm = importlib.import_module("jmcm")
    assert jmcm.name == "jmcm"

def test_make_blot_cells_adjacent():
    # Since blot grows from neighbors only, all cells must be adjacent to at least one other cell
    blot = make_blot([10,10], [1,1], 10)
    assert blot is not None
    cells = blot._cells
    if len(cells) > 1:
        for i, cell in enumerate(cells):
            if i == 0:
                continue
            # Check cell has at least one neighbor in previous cells (share edge)
            x,y = cell
            neighbors = [(x-1,y), (x+1,y), (x,y-1), (x,y+1)]
            assert any(neigh in cells[:i] for neigh in neighbors)

def test_jointmodel_is_a_class():
    jmcm = importlib.import_module("jmcm")
    assert isinstance(jmcm.JointModel, type)

def test_gelu_reexport_is_same_object_as_net_module():
    net = importlib.import_module("torch_gpt_2.net")
    assert torch_gpt_2.gelu is net.gelu

def test_gpt2_reexport_is_same_object_as_net_module():
    net = importlib.import_module("torch_gpt_2.net")
    assert torch_gpt_2.GPT_2 is net.GPT_2

def test_many_inserts_remain_findable():
    cuckoo = CuckooFilter(capacity=16, bucket_size=4, fingerprint_size=4)
    names = ["entry-%d" % n for n in range(40)]
    for name in names:
        assert cuckoo.insert(name) is True
    assert len(cuckoo) == 40
    for name in names:
        assert cuckoo.contains(name) is True

def test_jointmodel_module_path_is_expected():
    jmcm = importlib.import_module("jmcm")
    assert jmcm.JointModel.__module__ == "jmcm.joint_model"

def test_jointmodel_class_name_is_correct():
    jmcm = importlib.import_module("jmcm")
    assert jmcm.JointModel.__name__ == "JointModel"

def test_generate_reexport_is_same_object_as_gen_module():
    gen = importlib.import_module("torch_gpt_2.gen")
    assert torch_gpt_2.generate is gen.generate
